const budgetMs = 60_000;
let last = performance.now();
let timer = setTimeout(onSilent, budgetMs);
timer.unref();
function onMessage() {                    // consumer / subscription path
  last = performance.now();
  clearTimeout(timer);
  timer = setTimeout(onSilent, budgetMs);
  timer.unref();
}
function onSilent() {
  notifier.emit("silence", { subject, forMs: performance.now() - last });
}
